import { resolveClaim } from '../../../shared/scene/claims';
import type { Session } from './session';

// The memo is the founder's, in their words. Nothing is pre-filled or chosen for them: the decision starts empty. The
// evidence appendix is generated by code from the snapshots the founder actually looked at.

export type Choice = '' | 'A' | 'B' | 'C' | 'not_ready';

export interface Memo {
  choice: Choice;
  reasons: [string, string, string];
  conditions: string;
  watch: string;
}

export const EMPTY_MEMO: Memo = { choice: '', reasons: ['', '', ''], conditions: '', watch: '' };

/** Labels use each path's own plain description, not a verdict like "safer". */
export function choiceLabel(session: Session, c: Exclude<Choice, ''>): string {
  if (c === 'not_ready') return 'Not ready to decide yet';
  const p = session.paths[c];
  return `${c}: ${p.name}. ${p.summary}`;
}

export interface AppendixLine {
  label: string;
  scenario: string;
  value: string;
  path: string;
  snapshot: string;
  /** The profile revision the snapshot belongs to; an edit makes older rows historical. */
  revision: number;
  qualification?: string;
}

/**
 * Evidence for exactly the snapshots the founder looked at (in exploring or replay), most recent last.
 * Nothing is added for a path or scenario that was never viewed.
 */
export function evidenceAppendix(session: Session, viewedKeys: readonly string[]): AppendixLine[] {
  const lines: AppendixLine[] = [];
  const seen = new Set<string>();
  for (const key of viewedKeys) {
    if (seen.has(key)) continue;
    seen.add(key);
    const snap = session.registry.get(key);
    if (!snap) continue;
    const stressed = snap.ref.setback !== null;
    const refs = [
      { snapshotKey: key, scenario: 'baseline' as const, metric: 'lowest_cash' as const },
      ...(stressed
        ? [
            { snapshotKey: key, scenario: 'active' as const, metric: 'lowest_cash' as const },
            { snapshotKey: key, scenario: 'active' as const, metric: 'first_shortfall' as const },
          ]
        : [{ snapshotKey: key, scenario: 'baseline' as const, metric: 'first_shortfall' as const }]),
    ];
    for (const ref of refs) {
      const r = resolveClaim(session.registry, ref);
      if (!r.ok) continue;
      const c = r.claim;
      lines.push({
        label: c.label,
        scenario: c.scenarioLabel,
        value: c.text,
        path: c.pathId,
        snapshot: snap.inputHash,
        revision: snap.ref.profileRevision,
        ...(c.qualification ? { qualification: c.qualification } : {}),
      });
    }
  }
  return lines;
}

export const MEMO_FOOTER =
  'Demo founder: fictional. Synthetic inputs; template values are placeholders, not sourced figures. Not financial advice. One possible future, not a prediction.';
